// The deterministic AICS-1 fixtures of packages/aics-interop (generated by its generate.py, checked by its suite).
// Every file read here is checked against fixtures/manifest.json, so the client tests the exact committed bytes.
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
export const FIXTURES_DIR = fileURLToPath(new URL('../../../packages/aics-interop/fixtures/', import.meta.url));
export const manifest = JSON.parse(readFileSync(path.join(FIXTURES_DIR, 'manifest.json'), 'utf8'));
const consumed = new Set();
/** The exact bytes of a fixture file, after checking its SHA-256 and length against the manifest. */
export function fixtureBytes(name) {
  const meta = manifest.files[name];
  if (!meta) throw new Error(`${name} is not listed in the aics-interop manifest`);
  const bytes = readFileSync(path.join(FIXTURES_DIR, name));
  if (bytes.length !== meta.bytes || createHash('sha256').update(bytes).digest('hex') !== meta.sha256) throw new Error(`${name} differs from the aics-interop manifest`);
  consumed.add(name);
  return new Uint8Array(bytes);
}
export const interop = name => JSON.parse(Buffer.from(fixtureBytes(name)).toString('utf8'));
/** The tlog/tiles prefix as a path -> bytes map, every resource checked against the manifest. */
export function tileResources() {
  const root = path.join(FIXTURES_DIR, 'tlog/tiles'), out = {};
  const walk = dir => { for (const n of readdirSync(dir)) { const p = path.join(dir, n); if (n.startsWith('.')) continue; if (statSync(p).isDirectory()) walk(p); else { const rel = path.relative(root, p).split(path.sep).join('/'); out[rel] = fixtureBytes('tlog/tiles/' + rel); } } };
  walk(root); return out;
}
/** Fixture files (other than README.md and manifest.json) not read by any test so far. */
export const unconsumed = () => Object.keys(manifest.files).filter(f => !consumed.has(f) && f !== 'README.md' && f !== 'manifest.json');
export const hex = b => Buffer.from(b).toString('hex');
export const fromHex = h => new Uint8Array(Buffer.from(h, 'hex'));
export const fromB64 = s => new Uint8Array(Buffer.from(s, 'base64'));
export const fromU64 = s => new Uint8Array(Buffer.from(s, 'base64url'));
export const utf8 = s => new Uint8Array(Buffer.from(s, 'utf8'));
